import csv


def answer() -> int:
    # Dawid Majtyka -> Juliusz Dębosz -> Adam Gałach ->
    # Liwia Maligłówka -> Przemysław Kurczab.
    # Przemysław's children have 3, 0, 1, and 3 grandchildren:
    # Liwia Maligłówka, Julianna Paściak, Julita Kucharz, Alan Wocial.
    qualifying_children = {("Liwia", "Maligłówka"), ("Alan", "Wocial")}
    with open("/app/dataset/people_accounts.csv", newline="", encoding="utf-8") as f:
        return sum(
            int(row["account_balance"])
            for row in csv.DictReader(f)
            if (row["first_name"], row["last_name"]) in qualifying_children
        )


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
